3	//! `OutboxRelay`: the background drain that turns committed `event_outbox` rows into calls on
4	//! an injected [`EventPublisher`] (SMA-446, Slice B Task B8).
5	//!
6	//! **Multi-replica safety is the point.** Each tick runs entirely on one transaction:
7	//! 1. `SELECT * FROM event_outbox WHERE published_at IS NULL AND parked = false ORDER BY id
8	//!    FOR UPDATE SKIP LOCKED LIMIT batch_size` — locks the selected rows for the duration of the
9	//!    transaction, and `SKIP LOCKED` means a row already locked by ANOTHER relay replica's
10	//!    concurrent tick is silently excluded from this one's result set rather than blocking on
11	//!    it. Two replicas' `run` loops therefore never grab the same row.
12	//! 2. Each locked row is handed to `publisher.publish`; the outcome is written back on the SAME
13	//!    transaction (`published_at` on success, `attempts += 1` and — once `attempts` reaches
14	//!    `max_attempts` — `parked = true` on failure).
15	//! 3. `commit` releases the row locks.
16	//!
17	//! Verified against the vendored `sea-orm 1.1.20` (via `sea-query 0.32.7`, its lock-clause
18	//! backend): `QuerySelect::lock_with_behavior(LockType, LockBehavior)` and
19	//! `sea_orm::sea_query::{LockType::Update, LockBehavior::SkipLocked}` exist and map directly to
20	//! `FOR UPDATE SKIP LOCKED` — no raw-`Statement` fallback needed.
21	//!
22	//! [`OutboxRelay::run`] mirrors `PolicySnapshot::spawn_reload`'s shutdown-watch pattern
23	//! (`tokio::select!` racing a poll-interval sleep against a caller-supplied shutdown future) —
24	//! unlike `spawn_reload`, `run` does not `tokio::spawn` itself; the composition root (a later
25	//! task, B9) spawns it exactly like it already spawns the denial-audit drain in `main.rs`.
26	
27	use std::future::Future;
28	use std::sync::Arc;
29	use std::time::Duration;
30	
31	use chrono::Utc;
32	use metrics::{counter, gauge};
33	use paigasus_iam_core::{DomainEvent, EventPublisher, EventType};
34	use paigasus_observability::names;
35	use sea_orm::sea_query::{LockBehavior, LockType};
36	use sea_orm::{ActiveModelTrait, ColumnTrait, DatabaseConnection, DbErr, EntityTrait, IntoActiveModel, QueryFilter, QueryOrder, QuerySelect, Set, TransactionTrait};
37	
38	use crate::adapters::persistence::entities::event_outbox;
39	
40	/// Per-tick telemetry, both logged (`tracing::info!`) and returned so callers/tests can assert
41	/// on it directly instead of scraping log output.
42	#[derive(Debug, Default, Clone, Copy, PartialEq, Eq)]
43	pub struct TickReport {
44	    /// Rows locked and processed this tick (published + failed, including newly parked).
45	    pub drained: u64,
46	    /// Of `drained`, how many failed to publish (a subset that includes `parked`).
47	    pub failures: u64,
48	    /// Of `failures`, how many hit `max_attempts` and were parked this tick.
49	    pub parked: u64,
50	    /// Age (seconds) of the oldest row in this tick's batch, if the batch was non-empty — a
51	    /// cheap staleness signal (no extra query: derived from the already-fetched rows).
52	    pub oldest_unpublished_age_secs: Option<i64>,
53	}
54	
55	/// Reconstructs a [`DomainEvent`] from a persisted `event_outbox` row for handing to
56	/// [`EventPublisher::publish`]. Returns `Err` (a human-readable reason) for a malformed row — an
57	/// unrecognized `event_type` wire string, an out-of-range `schema_version`, or invalid `payload`
58	/// JSON — which should never happen for a row this relay's own writer (`PgOutbox::enqueue`, B2)
59	/// ever produced, but a defensive check here costs nothing next to a `panic!`/`unwrap()` that
60	/// would wedge the relay on a single corrupted row. The relay treats this exactly like a failed
61	/// `publish` call (counts against `attempts`, eventually parks).
62	fn row_to_domain_event(row: &event_outbox::Model) -> Result<DomainEvent, String> {
63	    let event_type = EventType::parse(&row.event_type).ok_or_else(|| format!("unrecognized event_type wire string {:?}", row.event_type))?;
64	    let schema_version = u16::try_from(row.schema_version).map_err(|_| format!("schema_version {} out of u16 range", row.schema_version))?;
65	    let payload = serde_json::from_str(&row.payload).map_err(|e| format!("invalid payload json: {e}"))?;
66	    Ok(DomainEvent {
67	        id: row.id,
68	        event_type,
69	        schema_version,
70	        aggregate_prn: row.aggregate_prn.clone(),
71	        actor_prn: row.actor_prn.clone(),
72	        occurred_at: row.occurred_at,
73	        payload,
74	        correlation_id: row.correlation_id,
75	    })
76	}
77	
78	/// The transactional-outbox relay: polls `event_outbox` for unpublished, unparked rows and
79	/// drains them through an injected [`EventPublisher`]. `Clone`: `DatabaseConnection` is an
80	/// `Arc`-backed pool handle (mirrors every other adapter in this crate), so the composition
81	/// root can hold a relay handle inside a `#[derive(Clone)]` service if it ever needs to.
82	#[derive(Clone)]
83	pub struct OutboxRelay {
84	    db: DatabaseConnection,
85	    poll_interval: Duration,
86	    batch_size: u64,
87	    max_attempts: i32,
88	}
89	
90	impl OutboxRelay {
91	    #[must_use]
92	    pub fn new(db: DatabaseConnection, poll_interval: Duration, batch_size: u64, max_attempts: i32) -> Self {
93	        OutboxRelay {
94	            db,
95	            poll_interval,
96	            batch_size,
97	            max_attempts,
98	        }
99	    }
100	
101	    /// Runs exactly one drain tick (the transactional-outbox pattern described in the module
102	    /// docs) and returns its [`TickReport`]. Public (not just used internally by [`Self::run`])
103	    /// so tests can drive individual, deterministic ticks rather than racing the poll loop.
104	    pub async fn tick(&self, publisher: &dyn EventPublisher) -> Result<TickReport, DbErr> {
105	        let txn = self.db.begin().await?;
106	
107	        let rows = event_outbox::Entity::find()
108	            .filter(event_outbox::Column::PublishedAt.is_null())
109	            .filter(event_outbox::Column::Parked.eq(false))
110	            .order_by_asc(event_outbox::Column::Id)
111	            .limit(self.batch_size)
112	            .lock_with_behavior(LockType::Update, LockBehavior::SkipLocked)
113	            .all(&txn)
114	            .await?;
115	
116	        let mut report = TickReport {
117	            drained: rows.len() as u64,
118	            oldest_unpublished_age_secs: rows.first().map(|r| Utc::now().signed_duration_since(r.occurred_at).num_seconds()),
119	            ..TickReport::default()
120	        };
121	
122	        for row in rows {
123	            let outcome = match row_to_domain_event(&row) {
124	                Ok(ev) => publisher.publish(&ev).await.map_err(|e| e.to_string()),
125	                Err(reason) => Err(reason),
126	            };
127	
128	            let mut active = row.clone().into_active_model();
129	            match outcome {
130	                Ok(()) => {
131	                    active.published_at = Set(Some(Utc::now()));
132	                }
133	                Err(reason) => {
134	                    report.failures += 1;
135	                    let attempts = row.attempts + 1;
136	                    active.attempts = Set(attempts);
137	                    if attempts >= self.max_attempts {
138	                        active.parked = Set(true);
139	                        report.parked += 1;
140	                        tracing::error!(id = %row.id, event_type = %row.event_type, attempts, reason = %reason, "outbox event parked after max attempts (poison)");
141	                    } else {
142	                        tracing::warn!(id = %row.id, event_type = %row.event_type, attempts, reason = %reason, "outbox event publish failed; will retry");
143	                    }
144	                }
145	            }
146	            active.update(&txn).await?;
147	        }
148	
149	        txn.commit().await?;
150	
151	        tracing::info!(
152	            drained = report.drained,
153	            failures = report.failures,
154	            parked = report.parked,
155	            oldest_unpublished_age_secs = report.oldest_unpublished_age_secs,
156	            "outbox relay tick"
157	        );
158	
159	        // SMA-446 Unit 5 (Task A11): per-tick relay counters/gauge, alongside the log line
160	        // above. `parked_total` is a COUNTER of newly-parked-this-tick rows (not a gauge —
161	        // the currently-parked-row-count is a derivable Prometheus query, `sum(increase(...))`,
162	        // not a separate series here).
163	        counter!(names::IAM_OUTBOX_RELAY_DRAINED_TOTAL).increment(report.drained);
164	        counter!(names::IAM_OUTBOX_RELAY_PUBLISH_FAILURES_TOTAL).increment(report.failures);
165	        counter!(names::IAM_OUTBOX_RELAY_PUBLISHED_TOTAL).increment(report.drained.saturating_sub(report.failures));
166	        counter!(names::IAM_OUTBOX_RELAY_PARKED_TOTAL).increment(report.parked);
167	        gauge!(names::IAM_OUTBOX_OLDEST_UNPUBLISHED_AGE_SECONDS).set(report.oldest_unpublished_age_secs.unwrap_or(0) as f64);
168	
169	        Ok(report)
170	    }
171	
172	    /// Runs the relay loop until `shutdown` resolves: sleep `poll_interval`, tick, repeat —
173	    /// mirrors `PolicySnapshot::spawn_reload`'s `tokio::select!` shutdown-watch exactly (sleep
174	    /// races shutdown first, so the very first tick runs after one poll interval, not
175	    /// immediately). A tick-level error (e.g. a dropped connection) is logged and the loop keeps
176	    /// going; per-row publish failures never reach here — [`Self::tick`] already turns those
177	    /// into `attempts`/`parked` bookkeeping on the same transaction.
178	    pub async fn run<S>(self, publisher: Arc<dyn EventPublisher>, shutdown: S)
179	    where
180	        S: Future<Output = ()> + Send,
181	    {
182	        tokio::pin!(shutdown);
183	        loop {
184	            tokio::select! {
185	                () = tokio::time::sleep(self.poll_interval) => {
186	                    match self.tick(publisher.as_ref()).await {
187	                        Ok(_) => {
188	                            counter!(names::IAM_OUTBOX_RELAY_TICKS_TOTAL, "result" => "ok").increment(1);
189	                        }
190	                        Err(err) => {
191	                            counter!(names::IAM_OUTBOX_RELAY_TICKS_TOTAL, "result" => "error").increment(1);
192	                            tracing::warn!(error = %err, "outbox relay tick failed; retrying next interval");
193	                        }
194	                    }
195	                }
196	                () = &mut shutdown => break,
197	            }
198	        }
199	    }
200	}
201	
202	#[cfg(test)]
203	mod tests {
204	    //! `row_to_domain_event` unit tests (SMA-446 Slice B Task B8, review finding, Fix 3): the
205	    //! three malformed-row error branches its own doc comment enumerates — an unrecognized
206	    //! `event_type` wire string, invalid `payload` JSON, and an out-of-range `schema_version`
207	    //! — each return `Err`, plus a well-formed row maps to the exact `DomainEvent` its fields
208	    //! describe. No DB needed: `event_outbox::Model` is hand-built, never persisted.
209	    use super::*;
210	    use uuid::Uuid;
211	
212	    /// A well-formed `event_outbox::Model` — every malformed-row test below starts from this
213	    /// and corrupts exactly the one field its case is about.
214	    fn base_model() -> event_outbox::Model {
215	        event_outbox::Model {
216	            id: Uuid::from_u128(1),
217	            occurred_at: Utc::now(),
218	            event_type: EventType::PrincipalCreated.as_wire().to_string(),
219	            schema_version: 1,
220	            aggregate_prn: "prn:pgs:iam:::principal/00000000-0000-0000-0000-0000000000aa".to_string(),
221	            actor_prn: Some("prn:pgs:iam:::principal/00000000-0000-0000-0000-0000000000bb".to_string()),
222	            payload: serde_json::json!({"kind": "user"}).to_string(),
223	            correlation_id: Some(Uuid::from_u128(2)),
224	            published_at: None,
225	            attempts: 0,
226	            parked: false,
227	        }
228	    }
229	
230	    #[test]
231	    fn rejects_unrecognized_event_type() {
232	        let mut row = base_model();
233	        row.event_type = "iam.nope.happened".to_string();
234	        let err = row_to_domain_event(&row).unwrap_err();
235	        assert!(err.contains("unrecognized event_type"), "unexpected error: {err}");
236	    }
237	
238	    #[test]
239	    fn rejects_invalid_payload_json() {
240	        let mut row = base_model();
241	        row.payload = "{not valid json".to_string();
242	        let err = row_to_domain_event(&row).unwrap_err();
243	        assert!(err.contains("invalid payload json"), "unexpected error: {err}");
244	    }
245	
246	    #[test]
247	    fn rejects_out_of_range_schema_version() {
248	        let mut negative = base_model();
249	        negative.schema_version = -1;
250	        let err = row_to_domain_event(&negative).unwrap_err();
251	        assert!(err.contains("schema_version"), "unexpected error: {err}");
252	
253	        let mut too_large = base_model();
254	        too_large.schema_version = i32::from(u16::MAX) + 1;
255	        let err = row_to_domain_event(&too_large).unwrap_err();
256	        assert!(err.contains("schema_version"), "unexpected error: {err}");
257	    }
258	
259	    #[test]
260	    fn maps_a_well_formed_row_to_the_matching_domain_event() {
261	        let row = base_model();
262	        let ev = row_to_domain_event(&row).unwrap();
263	        assert_eq!(ev.id, row.id);
264	        assert_eq!(ev.event_type, EventType::PrincipalCreated);
265	        assert_eq!(ev.schema_version, 1);
266	        assert_eq!(ev.aggregate_prn, row.aggregate_prn);
267	        assert_eq!(ev.actor_prn, row.actor_prn);
268	        assert_eq!(ev.occurred_at, row.occurred_at);
269	        assert_eq!(ev.payload, serde_json::json!({"kind": "user"}));
270	        assert_eq!(ev.correlation_id, row.correlation_id);
271	    }
272	}
