1	// SPDX-License-Identifier: Apache-2.0
2	
3	//! Integration tests for Task B8 (SMA-446, Slice B): the outbox relay's transactional
4	//! `SELECT ... FOR UPDATE SKIP LOCKED` drain, against real Postgres.
5	//!
6	//! Three scenarios, mirroring the task brief:
7	//! 1. a healthy publisher drains N seeded rows in one tick and marks each `published_at`;
8	//! 2. a publisher that always fails increments `attempts` each tick and parks the row once
9	//!    `attempts` reaches `max_attempts` (the poison path);
10	//! 3. `FOR UPDATE SKIP LOCKED` safety: a row locked by another, uncommitted transaction is
11	//!    skipped by the relay's tick rather than blocking on it or being double-processed — proven
12	//!    deterministically by holding the lock open across the relay's own tick rather than racing
13	//!    two ticks concurrently.
14	//!
15	//! Runs against an ephemeral Postgres in Docker. In CI (`CI` env set) a missing Docker daemon is
16	//! a HARD FAILURE; on a Docker-less laptop each test skips (returns) with a note — same gating
17	//! pattern as `tests/outbox_uow_pg.rs`/`tests/uow_mechanism_pg.rs`.
18	
19	mod support;
20	
21	use std::sync::Arc;
22	use std::sync::atomic::{AtomicUsize, Ordering};
23	use std::time::Duration;
24	
25	use async_trait::async_trait;
26	use chrono::Utc;
27	use paigasus_iam::adapters::events::OutboxRelay;
28	use paigasus_iam::adapters::persistence::entities::event_outbox;
29	use paigasus_iam_core::{DomainEvent, EventPublisher, EventType, PublishError};
30	use sea_orm::{ActiveModelTrait, ConnectionTrait, DatabaseConnection, DbBackend, EntityTrait, Set, Statement, TransactionTrait};
31	use uuid::Uuid;
32	
33	/// A publisher that always succeeds, counting how many events it has seen — the healthy-drain
34	/// assertion target for scenario 1.
35	#[derive(Default)]
36	struct CountingPublisher {
37	    count: AtomicUsize,
38	}
39	
40	#[async_trait]
41	impl EventPublisher for CountingPublisher {
42	    async fn publish(&self, _ev: &DomainEvent) -> Result<(), PublishError> {
43	        self.count.fetch_add(1, Ordering::SeqCst);
44	        Ok(())
45	    }
46	}
47	
48	/// A publisher that always fails — the poison-parking assertion target for scenario 2.
49	struct FailingPublisher;
50	
51	#[async_trait]
52	impl EventPublisher for FailingPublisher {
53	    async fn publish(&self, _ev: &DomainEvent) -> Result<(), PublishError> {
54	        Err(Box::<dyn std::error::Error + Send + Sync>::from("always fails").into())
55	    }
56	}
57	
58	/// Inserts one fresh, unpublished `event_outbox` row with the given `id`/`occurred_at`,
