109	/// Scenario 2 — poison parking: a row that always fails to publish accumulates `attempts` one
110	/// per tick, and is `parked` exactly once `attempts` reaches `max_attempts` — after which a
111	/// further tick leaves it untouched (parked rows are excluded from the drain query).
112	#[tokio::test]
113	async fn failing_publisher_parks_the_row_after_max_attempts() {
114	    let Some((_pg, db)) = support::start_migrated_postgres().await else { return };
115	
116	    let id = Uuid::from_u128(1);
117	    seed_row(&db, id, Utc::now()).await;
118	
119	    let max_attempts = 3;
120	    let relay = OutboxRelay::new(db.clone(), Duration::from_secs(60), 10, max_attempts);
121	    let publisher = FailingPublisher;
122	
123	    for expected_attempts in 1..=max_attempts {
124	        let report = relay.tick(&publisher).await.expect("tick succeeds even when the publisher fails");
125	        assert_eq!(report.drained, 1, "the still-unparked row keeps being picked up each tick");
126	        assert_eq!(report.failures, 1);
127	
128	        let row = event_outbox::Entity::find_by_id(id).one(&db).await.unwrap().expect("row still present");
129	        assert_eq!(row.attempts, expected_attempts, "attempts increments by one per failed tick");
130	        assert_eq!(row.published_at, None, "a failed publish never sets published_at");
131	
132	        let should_be_parked = expected_attempts >= max_attempts;
133	        assert_eq!(row.parked, should_be_parked, "parked flips true exactly once attempts reaches max_attempts");
134	        if should_be_parked {
135	            assert_eq!(report.parked, 1);
136	        } else {
137	            assert_eq!(report.parked, 0);
138	        }
139	    }
140	
141	    // One more tick: the now-parked row is excluded from the drain query entirely (no more
142	    // wasted publish attempts on a poisoned row), so attempts stays pinned at max_attempts.
143	    let report = relay.tick(&publisher).await.expect("tick succeeds with nothing left to drain");
144	    assert_eq!(report.drained, 0, "a parked row is never picked up again");
145	    let row = event_outbox::Entity::find_by_id(id).one(&db).await.unwrap().unwrap();
146	    assert_eq!(row.attempts, max_attempts, "attempts does not keep climbing once parked");
147	    assert!(row.parked);
148	}
